      "proposed_laureates": [
        "Adrian R. Krainer",
        "C. Frank Bennett"
      ],
      "assessment": {
        "nobel_worthiness": "Antisense correction of SMN2 splicing converted a molecular RNA principle into a major treatment for spinal muscular atrophy.",
        "attribution": "Krainer and Bennett form a focused and readily attributable pairing across splicing biology and therapeutic development.",
        "maturity": "Clinical efficacy and the wider validation of antisense therapeutics establish substantial maturity.",
        "uncertainties": [
          "The degree to which the recognition should be limited to SMN2 correction rather than the broader antisense platform is uncertain."
        ]
      }
    },
